def GetComp(d):
    '''Concentration matrix of complementary 2-mers
    Inputs:
    d: concentration of 2-mers, numpy float array with dimensions [Z, Z]
    Outputs:
    dcomp: concentration of 2-mers, numpy float array with dimensions [Z, Z], where dcomp[i, j]==d[j', i'].
    '''
    Z = d.shape[0]
    dcomp = np.zeros((Z, Z))
    for i in range(Z):
        for j in range(Z):
            if i < Z // 2:
                j_prime = j + Z // 2
            else:
                j_prime = j - Z // 2
            if i < Z // 2:
                i_prime = i + Z // 2
            else:
                i_prime = i - Z // 2
            dcomp[i, j] = d[j_prime, i_prime]
    return dcomp
